def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None

    maxlen = max(len(x) for x in strings)
    for s in strings:
        if len(s) == maxlen:
            return s

def is_palindrome(string: str) -> bool:
    """ Test if given string is a palindrome """
    return string == string[::-1]


def make_palindrome(string: str) -> str:
    if not string:
        return ''

    beginning_of_suffix = 0

    # Find the longest postfix that is a palindrome
    # by checking suffixes starting from index 0, 1, 2...
    while not is_palindrome(string[beginning_of_suffix:]):
        beginning_of_suffix += 1

    # Append the reverse of the prefix that precedes the palindromic suffix
    return string + string[:beginning_of_suffix][::-1]

def string_xor(a: str, b: str) -> str:
    """
    Performs binary XOR on two strings consisting of 1s and 0s.
    """
    return "".join('1' if a[i] != b[i] else '0' for i in range(len(a)))

