def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    begin, end = -1., 1.
    # Expand the range until the signs of the polynomial at the boundaries are different
    # This is guaranteed to happen for polynomials of odd degree (even number of coefficients)
    while poly(xs, begin) * poly(xs, end) > 0:
        begin *= 2.0
        end *= 2.0

    # Binary search (Bisection method) to find the root
    # We use a fixed number of iterations or a precision threshold
    for _ in range(100):
        center = (begin + end) / 2.0
        if poly(xs, center) * poly(xs, begin) > 0:
            begin = center
        else:
            end = center

    return (begin + end) / 2.0

def max_element(l: list):
    """
    Return maximum element in the list.
    """
    return max(l)

