def encode(message):
    vowels = "aeiouAEIOU"
    result = []
    for char in message:
        if char.isalpha():
            # Swap case
            swapped = char.swapcase()
            # Check if the original character was a vowel
            if char in vowels:
                # Replace with letter 2 places ahead in alphabet
                # ord() gets ASCII, +2 moves it, chr() converts back
                result.append(chr(ord(swapped) + 2))
            else:
                result.append(swapped)
        else:
            result.append(char)
    return "".join(result)
