import math

def closest_integer(value):
    """
    Returns the closest integer to the given value. 
    If equidistant, rounds away from zero.
    """
    num = float(value)

    # Check if the number is exactly halfway between two integers
    # We use modulo 1 to check for the .5 case
    if abs(num) % 1 == 0.5:
        if num > 0:
            return math.ceil(num)
        else:
            return math.floor(num)

    # For all other cases, standard rounding to nearest integer works.
    # Python's round() rounds to the nearest even number for .5, 
    # but since we handled .5 above, round() is safe here.
    return int(round(num))
