            first_digit = int(s_num[1])
            digit_sum += -first_digit
            for char in s_num[2:]:
                digit_sum += int(char)
        else:
            # All digits are positive
            for char in s_num:
                digit_sum += int(char)

        if digit_sum > 0:
            count += 1
    return count
