def exchange(lst1, lst2):
    # Count how many odd numbers are currently in lst1.
    # These are the elements that MUST be replaced by even numbers from lst2.
    odds_in_lst1 = 0
    for i in lst1:
        if i % 2 != 0:
            odds_in_lst1 += 1

    # Count how many even numbers are available in lst2 to be swapped into lst1.
    evens_in_lst2 = 0
    for i in lst2:
        if i % 2 == 0:
            evens_in_lst2 += 1

    # If the number of available even numbers in lst2 is at least 
    # the number of odd numbers in lst1, we can make lst1 all even.
    if evens_in_lst2 >= odds_in_lst1:
        return "YES"
    else:
        return "NO"
