def histogram(test):
    if not test:
        return {}

    list1 = test.split(" ")
    # Filter out empty strings resulting from multiple spaces
    list1 = [i for i in list1 if i != '']

    if not list1:
        return {}

    # Count occurrences of each letter
    counts = {}
    for i in list1:
        counts[i] = counts.get(i, 0) + 1

    # Find the maximum frequency
    max_count = max(counts.values())

    # Return all letters that have the maximum frequency
    return {k: v for k, v in counts.items() if v == max_count}
