def sort_array(arr):
    # Sort by the number of ones in binary representation, 
    # then by the decimal value itself for ties.
    # bin(x).count('1') counts the set bits.
    return sorted(arr, key=lambda x: (bin(x).count('1'), x))

def max_fill(grid, capacity):
    import math
    # For each well (row), calculate the total amount of water (sum of 1s).
    # The number of times a bucket must be lowered for a specific well is 
    # the total water divided by capacity, rounded up (ceiling).
    return sum([math.ceil(sum(row) / capacity) for row in grid])

