def get_odd_collatz(n):
    """
    Returns a sorted list of odd numbers in the Collatz sequence starting from n.
    """
    odds = []
    current = n

    while True:
        if current % 2 != 0:
            odds.append(current)

        if current == 1:
            break

        if current % 2 == 0:
            current = current // 2
        else:
            current = 3 * current + 1

    return sorted(odds)
