    intersect_end = min(end1, end2)

    # Check if the intervals intersect
    if intersect_start <= intersect_end:
        # Length of a closed interval [a, b] is b - a
        length = intersect_end - intersect_start
        if is_prime(length):
            return "YES"
        else:
            return "NO"
    else:
        # No intersection
        return "NO"
