def prod_signs(arr):
    if not arr:
        return None

    # Calculate the product of signs:
    # If any element is 0, the product of signs is 0.
    # Otherwise, the product is 1 if there's an even number of negative signs, and -1 if odd.
    if 0 in arr:
        sign_prod = 0
    else:
        neg_count = len([x for x in arr if x < 0])
        sign_prod = 1 if neg_count % 2 == 0 else -1

    # Return the sum of magnitudes multiplied by the product of signs
    return sign_prod * sum(abs(x) for x in arr)
