def minPath(grid, k):
    n = len(grid)
    # The goal is to find the lexicographically smallest path of length k.
    # The smallest possible value in the grid is 1.
    # To make the path lexicographically smallest, we must start at the cell containing 1.
    # Then, for the second element, we must move to the smallest possible neighbor of 1.
    # Once we are at that smallest neighbor, the best move for the third element is to 
    # move back to the cell containing 1 (since 1 is the smallest value in the grid).
    # This pattern (1, min_neighbor, 1, min_neighbor, ...) will always yield the 
    # lexicographically smallest sequence.

    # Find the position of 1
    start_r, start_c = -1, -1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                start_r, start_c = r, c
                break
        if start_r != -1:
            break

    # If k is 1, the path is just [1]
    if k == 1:
        return [1]

    # Find the smallest neighbor of the cell containing 1
    min_neighbor = float('inf')
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = start_r + dr, start_c + dc
        if 0 <= nr < n and 0 <= nc < n:
            if grid[nr][nc] < min_neighbor:
                min_neighbor = grid[nr][nc]

    # Construct the path: 1, min_neighbor, 1, min_neighbor...
    ans = []
    for i in range(k):
        if i % 2 == 0:
            ans.append(1)
        else:
            ans.append(min_neighbor)

    return ans
