def fix_spaces(text):
    import re
    # Replace 3 or more consecutive spaces with '-'
    # Replace 1 or 2 consecutive spaces with '_' for each space
    # We use a regex to find sequences of spaces
    def replace_match(match):
        s = match.group(0)
        if len(s) > 2:
            return "-"
        else:
            return "_" * len(s)

    return re.sub(r' +', replace_match, text)
